    $cms${"schemaVersion":1,"sections":[{"id":"hero","type":"hero","props":{"eyebrow":"Escritura · Reflexión · Herramientas personales","headingLine1":"Nuestra","headingLine2":"medicina personal","lede":"Un espacio para escribir, mirar hacia adentro y encontrarnos con nuestras propias herramientas.","primaryCtaLabel":"Explorar los libros","primaryCtaTo":"/libros","secondaryCtaLabel":"Conocer el proyecto →","secondaryCtaTo":"#sobre-el-proyecto","imageCaption":"Foto — amanecer sobre paisaje natural"}},{"id":"galeria","type":"gallery","props":{"captions":["Naturaleza en calma","El amanecer","Cielo estrellado","Una tarde en el pasto","Gratitud en la mesa","Asombro frente a lo vivo"]}},{"id":"manifiesto","type":"manifesto","props":{"quote":"Hay historias que también nos ayudan a mirarnos.","body":"Nuestra Medicina Personal reúne escritura, reflexión y herramientas para acompañar procesos de exploración personal y educativa."}},{"id":"libros","type":"featured-books","props":{"eyebrow":"Colección","title":"Libros destacados","description":"Escritura y educación para acompañar tus propios procesos."}},{"id":"meditaciones","type":"collection-teaser","props":{"eyebrow":"Colección","title":"Meditaciones","description":"Prácticas breves para volver a habitar el cuerpo y la respiración.","ctaLabel":"Explorar meditaciones","ctaTo":"/meditaciones","imageCaption":"Colección — Meditaciones","reverse":false,"accent":"sky"}},{"id":"herramientas","type":"collection-teaser","props":{"eyebrow":"Colección","title":"Caja de herramientas personales","description":"Recursos simples para sostener la escritura y la reflexión en el día a día.","ctaLabel":"Explorar herramientas","ctaTo":"/herramientas","imageCaption":"Colección — Caja de herramientas personales","reverse":true,"accent":"amber"}},{"id":"about","type":"about","props":{"eyebrow":"Sobre el proyecto","title":"Quién escribe estas páginas","bio":"Nombre del autor/a — breve biografía editable sobre su recorrido en la escritura, la educa