    $cms${"schemaVersion":1,"sections":[{"id":"faq","type":"faq","props":{"title":"Preguntas frecuentes","intro":"Las dudas más comunes sobre libros, compras y tu cuenta.","faqs":[{"id":"f1","q":"¿En qué formato recibo los libros?","a":"Todos los libros están disponibles en PDF y EPUB, así podés elegir el formato que prefieras para tu dispositivo."},{"id":"f2","q":"¿Cómo accedo a mis libros después de comprarlos?","a":"Todos tus libros quedan disponibles en \"Mi biblioteca\" apenas Mercado Pago confirma el pago."},{"id":"f3","q":"¿Puedo pedir un reembolso?","a":"Sí, dentro de los 10 días de la compra y siempre que no hayas descargado el libro. Escribinos a soporte@nuestramedicinapersonal.com."},{"id":"f4","q":"¿Necesito una cuenta para comprar?","a":"Sí, iniciás sesión con tu cuenta de Google para poder acceder a tus compras desde cualquier dispositivo."}]}}]}$cms$::jsonb, $cms${"schemaVersion":1,"sections":[{"id":"faq","type":"faq","props":{"title":"Preguntas frecuentes","intro":"Las dudas más comunes sobre libros, compras y tu cuenta.","faqs":[{"id":"f1","q":"¿En qué formato recibo los libros?","a":"Todos los libros están disponibles en PDF y EPUB, así podés elegir el formato que prefieras para tu dispositivo."},{"id":"f2","q":"¿Cómo accedo a mis libros después de comprarlos?","a":"Todos tus libros quedan disponibles en \"Mi biblioteca\" apenas Mercado Pago confirma el pago."},{"id":"f3","q":"¿Puedo pedir un reembolso?","a":"Sí, dentro de los 10 días de la compra y siempre que no hayas descargado el libro. Escribinos a soporte@nuestramedicinapersonal.com."},{"id":"f4","q":"¿Necesito una cuenta para comprar?","a":"Sí, iniciás sesión con tu cuenta de Google para poder acceder a tus compras desde cualquier dispositivo."}]}}]}$cms$::jsonb, now()
)
